class Words2Numbers:

    ZERO_SCALES = [10 ** 2, 10 ** 3, 10 ** 6, 10 ** 9, 10 ** 12]

    def __init__(self):
        self._numwords = {}
        self.units = [
            "zero", "one", "two", "three", "four", "five", "six", "seven", "eight",
            "nine", "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen",
            "sixteen", "seventeen", "eighteen", "nineteen",
        ]
        self.tens = ["", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"]
        self.scales = ["hundred", "thousand", "million", "billion", "trillion"]

        self.numwords = {}
        for idx, word in enumerate(self.units):
            self.numwords[word] = (1, idx)
        for idx, word in enumerate(self.tens):
            self.numwords[word] = (1, idx * 10)
        for idx, word in enumerate(self.scales):
            self.numwords[word] = (self.ZERO_SCALES[idx], 0)

        self.ordinal_words = {'first': 1, 'second': 2, 'third': 3, 'fifth': 5, 'eighth': 8, 'ninth': 9, 'twelfth': 12}
        self.ordinal_endings = [('ieth', 'y'), ('th', '')]

    @property
    def numwords(self):
        return self._numwords

    @numwords.setter
    def numwords(self, value):
        self._numwords = value

    def text2int(self, textnum):
        textnum = textnum.replace('-', ' ')
        words = textnum.split()
        current, result = self._process_number_words(words)
        return self._build_output_string(result, current, self._extract_non_number_words(words, result, current))

    def _process_number_words(self, words):
        current = 0
        result = 0
        onnumber = False
        for word in words:
            if word in self.ordinal_words:
                scale, increment = (1, self.ordinal_words[word])
                current = current * scale + increment
                onnumber = True
            else:
                word = self._strip_ordinal_ending(word)
                if word not in self.numwords:
                    if onnumber:
                        result += current
                        current = 0
                    onnumber = False
                else:
                    scale, increment = self.numwords[word]
                    current = current * scale + increment
                    if scale > 100:
                        result += current
                        current = 0
                    onnumber = True
        if onnumber:
            result += current
        return current, result

    def _strip_ordinal_ending(self, word):
        for ending, replacement in self.ordinal_endings:
            if word.endswith(ending):
                word = "%s%s" % (word[:-len(ending)], replacement)
                break
        return word

    def _extract_non_number_words(self, words, result, current):
        non_number_words = []
        onnumber = False
        for word in words:
            if word in self.ordinal_words:
                onnumber = True
            else:
                word = self._strip_ordinal_ending(word)
                if word not in self.numwords:
                    non_number_words.append(word)
                    onnumber = False
        return ' '.join(non_number_words) if non_number_words else ""

    def _build_output_string(self, result, current, non_number_words):
        if result + current > 0:
            numeric_part = str(result + current)
            if non_number_words:
                return "{} {}".format(numeric_part, non_number_words)
            return numeric_part
        if non_number_words:
            return non_number_words
        return ""

    def is_valid_input(self, textnum):
        textnum = textnum.replace('-', ' ')
        for word in textnum.split():
            if word in self.ordinal_words:
                continue
            word = self._strip_ordinal_ending(word)
            if word not in self.numwords:
                return False
        return True
